const input = $input.first().json;
const body = input.body ?? input;
const userId = Number(body.user_id);
const requestedLimit = body.limit === undefined ? 5 : Number(body.limit);

if (!Number.isSafeInteger(userId) || userId < 1) {
  throw new Error('Invalid user_id');
}

if (!Number.isSafeInteger(requestedLimit) || requestedLimit < 1 || requestedLimit > 5) {
  throw new Error('Invalid limit; expected an integer from 1 to 5');
}

return [{ json: {
  user_id: userId,
  limit: requestedLimit,
  requested_at: new Date().toISOString(),
  execution_id: String($execution.id)
} }];

let source = $input.first().json;
if (Array.isArray(source) && source.length === 1) source = source[0];
if (source?.data && typeof source.data === 'object') source = source.data;
if (typeof source === 'string') source = JSON.parse(source);

const context = $('Validate Request').first().json;
if (!source || typeof source !== 'object') throw new Error('Recommendation data not found');
if (Number(source.user_id) !== context.user_id) throw new Error('Recommendation user mismatch');
if (!Array.isArray(source.products)) throw new Error('Products not found in recommendation data');

const products = source.products
  .filter((product) => Number.isSafeInteger(Number(product.product_id)) && Number(product.stock_quantity) > 0)
  .slice(0, 50)
  .map((product) => ({
    product_id: Number(product.product_id),
    product_name: String(product.product_name ?? ''),
    category_id: Number(product.category_id),
    category_name: product.category_name ?? null,
    description: String(product.description ?? '').slice(0, 300),
    price: Number(product.price ?? 0),
    unit: product.unit ?? null,
    image_url: product.image_url ?? null,
    production_source: String(product.production_source ?? '').slice(0, 160) || null,
    stock_quantity: Number(product.stock_quantity),
    user_view_count: Math.max(0, Number(product.user_view_count) || 0),
    category_affinity: Math.max(0, Number(product.category_affinity) || 0),
    global_views_90d: Math.max(0, Number(product.global_views_90d) || 0),
    last_viewed_at: product.last_viewed_at ?? null
  }));

if (products.length === 0) throw new Error('No active in-stock products available');

const userBehavior = Array.isArray(source.user_behavior)
  ? source.user_behavior.slice(0, 50).map((row) => ({
      product_id: Number(row.product_id),
      category_id: Number(row.category_id),
      view_count: Math.max(0, Number(row.view_count) || 0),
      last_viewed_at: row.last_viewed_at ?? null
    }))
  : [];

return [{ json: {
  user_id: context.user_id,
  limit: context.limit,
  user_behavior: userBehavior,
  products
} }];

const aiResult = $input.first().json;
const source = $('Prepare AI Input').first().json;
let output = aiResult.output ?? aiResult.text ?? aiResult.response ?? aiResult.content ?? aiResult;
if (output && typeof output === 'object') output = output.output ?? output.text ?? output.response ?? output.content ?? output;

let parsed = output;
if (typeof output === 'string') {
  let cleaned = output.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  if (firstBrace >= 0 && lastBrace > firstBrace) cleaned = cleaned.slice(firstBrace, lastBrace + 1);
  parsed = JSON.parse(cleaned);
}
if (!Array.isArray(parsed?.recommendations)) throw new Error('AI did not return recommendations');

const productMap = new Map(source.products.map((product) => [product.product_id, product]));
const seen = new Set();
const recommendations = [];

for (const item of parsed.recommendations) {
  const productId = Number(item.product_id);
  if (!Number.isSafeInteger(productId) || !productMap.has(productId) || seen.has(productId)) continue;
  const product = productMap.get(productId);
  seen.add(productId);
  recommendations.push({
    product_id: productId,
    product_name: product.product_name,
    category_id: product.category_id,
    category_name: product.category_name,
    description: product.description || null,
    price: product.price,
    unit: product.unit,
    image_url: product.image_url,
    production_source: product.production_source,
    stock_quantity: product.stock_quantity,
    score: Math.max(0, Math.min(100, Math.round(Number(item.score) || 0))),
    reason: String(item.reason || 'สินค้าแนะนำสำหรับคุณ').trim().slice(0, 160)
  });
}

recommendations.sort((a, b) => b.score - a.score || a.product_id - b.product_id);

for (const product of source.products) {
  if (recommendations.length >= source.limit) break;
  if (seen.has(product.product_id)) continue;
  seen.add(product.product_id);
  const score = Math.min(100, Math.round(35 + Math.min(product.user_view_count, 10) * 3 + Math.min(product.category_affinity, 20) * 2 + Math.min(product.global_views_90d, 20)));
  recommendations.push({
    product_id: product.product_id,
    product_name: product.product_name,
    category_id: product.category_id,
    category_name: product.category_name,
    description: product.description || null,
    price: product.price,
    unit: product.unit,
    image_url: product.image_url,
    production_source: product.production_source,
    stock_quantity: product.stock_quantity,
    score,
    reason: product.user_view_count > 0 ? 'จากสินค้าที่คุณเคยเข้าชม' : product.category_affinity > 0 ? 'อยู่ในหมวดหมู่ที่คุณสนใจ' : 'สินค้าที่กำลังได้รับความสนใจ'
  });
}

return [{ json: {
  user_id: source.user_id,
  strategy: source.user_behavior.length > 0 ? 'ai-personalized' : 'ai-popular',
  generated_at: new Date().toISOString(),
  recommendations: recommendations.slice(0, source.limit)
} }];

const source = $('Prepare AI Input').first().json;
const recommendations = source.products.slice(0, source.limit).map((product) => {
  const score = Math.min(100, Math.round(35 + Math.min(product.user_view_count, 10) * 3 + Math.min(product.category_affinity, 20) * 2 + Math.min(product.global_views_90d, 20)));
  return {
    product_id: product.product_id,
    product_name: product.product_name,
    category_id: product.category_id,
    category_name: product.category_name,
    description: product.description || null,
    price: product.price,
    unit: product.unit,
    image_url: product.image_url,
    production_source: product.production_source,
    stock_quantity: product.stock_quantity,
    score,
    reason: product.user_view_count > 0 ? 'จากสินค้าที่คุณเคยเข้าชม' : product.category_affinity > 0 ? 'อยู่ในหมวดหมู่ที่คุณสนใจ' : 'สินค้าที่กำลังได้รับความสนใจ'
  };
});
return [{ json: {
  user_id: source.user_id,
  strategy: source.user_behavior.length > 0 ? 'fallback-personalized' : 'fallback-popular',
  generated_at: new Date().toISOString(),
  recommendations
} }];

const item = $input.first().json ?? {};
const rawMessage = item.error?.message ?? item.message ?? item.description ?? 'Recommendation workflow failed';
const message = String(rawMessage).slice(0, 500);
const invalidRequest = /invalid user_id|invalid limit/i.test(message);
const notFound = /active customer not found|no active in-stock products/i.test(message);
return [{ json: {
  status_code: invalidRequest ? 400 : notFound ? 404 : 502,
  body: {
    success: false,
    message: invalidRequest ? 'Invalid recommendation request' : notFound ? 'Recommendation data not found' : 'Unable to generate recommendations',
    error: message
  }
} }];
